/** Position (x, y) d'un point de latitude et longitude données sur la carte. */
function sueb_point_carte( $lat, $lon ) {
	return array( round( ( $lon - 8.0 ) * 50 * 0.991445, 1 ), round( ( 13.6 - $lat ) * 50, 1 ) );
}
